import re
from datetime import datetime, timezone

AADHAAR = re.compile(r"\b\d{4}\s?\d{4}\s?(\d{4})\b")
PAN = re.compile(r"\b[A-Z]{5}\d{4}[A-Z]\b")

def mask(text: str) -> str:
    """Keep only the last four Aadhaar digits; tokenise PAN."""
    text = AADHAAR.sub(lambda m: "XXXX XXXX " + m.group(1), text)
    return PAN.sub(lambda m: token_for(m.group(0)), text)

def record_consent(customer_id, purpose, notice_version, lang):
    return consent_store.insert({
        "customer_id": customer_id, "purpose": purpose,        # one purpose per record
        "notice_version": notice_version, "language": lang,
        "given_at": datetime.now(timezone.utc).isoformat(), "withdrawn_at": None})

def ask_model(customer_id, purpose, text):
    if not consent_store.active(customer_id, purpose):
        raise PermissionError(f"no active consent for {purpose}")
    return vendor_llm.complete(mask(text))                     # vendor bound by a processor contract

STORES = [primary_db, vector_store, agent_memory, cache, log_archive]

def erase(customer_id):
    """Erasure must reach every copy, not just the main database."""
    results = {s.name: s.delete_customer(customer_id) for s in STORES}
    assert all(results.values()), f"erasure incomplete: {results}"
    return results
